36		eventPlanRevoke = "保养撤销"
37		eventPlanAdjust = "保养调整"
38	
39		eventPartWithdraw = "领用"
40		eventPartReturn   = "退回"
41	
42		eventAttach       = "附件登记"
43		eventAttachRevoke = "附件撤销"
