179	// PartWithdrawal 为一笔备件领用记录，ID 即领用编号（同目录唯一、不复用）。
180	// 数量表示工单用量；Returned 为累计退回数量，净量 = Quantity - Returned。
181	// 工单关闭或取消后记录与净量保留，不清零。
182	type PartWithdrawal struct {
183		ID       string `json:"id"`
184		TicketID string `json:"ticket_id"`
185		AssetID  string `json:"asset_id"`
