254	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
255	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
256	func openStore(dir string) (*store, error) {
257		return loadStore(dir, true)
258	}
259	
260	// openSourceStore 以只读用途打开导入源数据目录：与 openStore 做同样的整库
261	// 一致性检查，但源台账必须已存在——不存在时报错，绝不能当空库初始化。
262	func openSourceStore(dir string) (*store, error) {
263		return loadStore(dir, false)
264	}
265	
266	func loadStore(dir string, allowMissing bool) (*store, error) {
267		path := filepath.Join(dir, dataFileName)
268		raw, err := os.ReadFile(path)
269		if err != nil {
270			if errors.Is(err, os.ErrNotExist) {
271				if allowMissing {
272					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
273				}
274				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
275			}
276			return nil, fmt.Errorf("读取数据文件失败: %w", err)
277		}
278		if len(bytes.TrimSpace(raw)) == 0 {
279			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
280		}
281		var d storeData
282		if err := json.Unmarshal(raw, &d); err != nil {
283			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
284		}
285		if d.EventsJSON != nil {
286			d.Events = make([]Event, len(d.EventsJSON))
287			for i, ej := range d.EventsJSON {
288				ev, err := ej.toEvent()
289				if err != nil {
290					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
291				}
292				d.Events[i] = ev
293			}
294		}
295		// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
296		if d.Plans == nil {
297			d.Plans = []*Plan{}
298		}
299		// 无备件字段的有效旧库直接使用：缺省视为没有任何备件领用记录，
300		// 领用编号计数器从 1 开始。
301		if d.Parts == nil {
302			d.Parts = []*PartWithdrawal{}
303		}
304		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
305			d.NextPartSeq = 1
306		}
307		// 无附件字段的有效旧库直接使用：缺省视为没有任何附件索引记录，
308		// 附件编号计数器从 1 开始。
309		if d.Attachments == nil {
310			d.Attachments = []*Attachment{}
311		}
312		if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
313			d.NextAttachSeq = 1
314		}
315		if err := validateData(&d); err != nil {
316			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
317		}
318		return &store{dir: dir, data: &d, now: time.Now}, nil
319	}
320	
321	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
322	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
323	func parseTicketSeq(id string) (int, bool) {
324		if !strings.HasPrefix(id, "T") {
325			return 0, false
326		}
327		n, err := strconv.Atoi(id[1:])
328		if err != nil || n < 1 {
329			return 0, false
330		}
331		if fmt.Sprintf("T%04d", n) != id {
332			return 0, false
333		}
334		return n, true
335	}
336	
337	// parsePartSeq 解析 P 加补零正整数序号形式的领用编号，返回序号。
338	// 编号必须与 fmt.Sprintf("P%04d", n)（n ≥ 1）完全一致，否则视为非法。
339	func parsePartSeq(id string) (int, bool) {
340		if !strings.HasPrefix(id, "P") {
341			return 0, false
342		}
343		n, err := strconv.Atoi(id[1:])
344		if err != nil || n < 1 {
345			return 0, false
346		}
347		if fmt.Sprintf("P%04d", n) != id {
348			return 0, false
349		}
350		return n, true
351	}
352	
353	// parseAttachSeq 解析 A 加补零正整数序号形式的附件编号，返回序号。
354	// 编号必须与 fmt.Sprintf("A%04d", n)（n ≥ 1）完全一致，否则视为非法。
355	func parseAttachSeq(id string) (int, bool) {
356		if !strings.HasPrefix(id, "A") {
357			return 0, false
358		}
359		n, err := strconv.Atoi(id[1:])
360		if err != nil || n < 1 {
361			return 0, false
362		}
363		if fmt.Sprintf("A%04d", n) != id {
364			return 0, false
365		}
366		return n, true
367	}
368	
369	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
370	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
371	// 不做任何修复：不补字段、不重编号、不删除记录。
372	func validateData(d *storeData) error {
373		if d.Version != storeVersion {
374			return fmt.Errorf("不支持的数据版本 %d", d.Version)
375		}
376		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil || d.Plans == nil || d.Parts == nil || d.Attachments == nil {
377			return errors.New("缺少必要的数据段")
378		}
379		assets := map[string]*Asset{}
380		for _, a := range d.Assets {
381			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
382				return errors.New("数据矛盾：存在字段不完整的资产记录")
383			}
384			if a.Status != statusAvailable && a.Status != statusRepairing && a.Status != statusDeactivated {
385				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
386			}
387			if assets[a.ID] != nil {
388				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
389			}
390			assets[a.ID] = a
391		}
392		tickets := map[string]*Ticket{}
393		maxTicketSeq := 0
394		for _, t := range d.Tickets {
395			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
396				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
397			}
398			n, ok := parseTicketSeq(t.ID)
399			if !ok {
400				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
401			}
402			if n > maxTicketSeq {
403				maxTicketSeq = n
404			}
405			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
406				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
407			}
408			if assets[t.AssetID] == nil {
409				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
410			}
411			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
412				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
413			}
414			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
415				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
416			}
417			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
418				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
419			}
420			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
421				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
422			}
423			if t.Assignee == "" {
424				if t.AssignedAt != "" || t.AssignNote != "" {
425					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
426				}
427			} else if t.AssignedAt == "" || t.AssignNote == "" {
428				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
429			}
430			if tickets[t.ID] != nil {
431				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
432			}
433			tickets[t.ID] = t
434		}
435		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
436		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
437			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
438				d.NextTicketSeq, maxTicketSeq)
439		}
440		// 备件领用记录：编号唯一且为 P 加补零正整数序号，归属存在的工单且资产归属
441		// 与工单一致，数量为正，累计退回在 [0, 原数量] 内；与履历的接续在下方按
442		// 履历序号重放时核对。
443		parts := map[string]*PartWithdrawal{}
444		maxPartSeq := 0
445		for _, p := range d.Parts {
446			if p == nil || p.ID == "" || p.TicketID == "" || p.AssetID == "" || p.PartID == "" || p.Note == "" {
447				return errors.New("数据矛盾：存在字段不完整的备件领用记录")
448			}
449			n, ok := parsePartSeq(p.ID)
450			if !ok {
451				return fmt.Errorf("计数器矛盾：领用编号 %q 不是 P 加补零正整数序号的形式", p.ID)
452			}
453			if n > maxPartSeq {
454				maxPartSeq = n
455			}
456			if p.Quantity < 1 {
457				return fmt.Errorf("数据矛盾：领用记录 %s 的数量 %d 不是正整数", p.ID, p.Quantity)
458			}
459			if p.Returned < 0 || p.Returned > p.Quantity {
460				return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回 %d 超出原数量 %d", p.ID, p.Returned, p.Quantity)
461			}
462			t := tickets[p.TicketID]
463			if t == nil {
464				return fmt.Errorf("数据矛盾：领用记录 %s 引用了不存在的工单 %s", p.ID, p.TicketID)
465			}
466			if t.AssetID != p.AssetID {
467				return fmt.Errorf("数据矛盾：领用记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
468					p.ID, p.AssetID, t.ID, t.AssetID)
469			}
470			if parts[p.ID] != nil {
471				return fmt.Errorf("数据矛盾：领用编号 %s 重复", p.ID)
472			}
473			parts[p.ID] = p
474		}
475		// 下一领用序号必须为正并大于全部已用序号（允许有间隔）。
476		if d.NextPartSeq < 1 || d.NextPartSeq <= maxPartSeq {
477			return fmt.Errorf("计数器矛盾：下一领用序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
478				d.NextPartSeq, maxPartSeq)
479		}
480		// 附件索引记录：编号唯一且为 A 加补零正整数序号，归属存在的工单且资产归属
481		// 与工单一致，路径为绝对路径，说明非空；撤销状态与理由相互呼应。文件当前
482		// 是否可用不参与整库一致性校验；与履历的接续在下方按履历序号重放时核对。
483		attachments := map[string]*Attachment{}
484		maxAttachSeq := 0
485		for _, a := range d.Attachments {
486			if a == nil || a.ID == "" || a.TicketID == "" || a.AssetID == "" || a.Path == "" || a.Note == "" {
487				return errors.New("数据矛盾：存在字段不完整的附件记录")
488			}
489			n, ok := parseAttachSeq(a.ID)
490			if !ok {
491				return fmt.Errorf("计数器矛盾：附件编号 %q 不是 A 加补零正整数序号的形式", a.ID)
492			}
493			if n > maxAttachSeq {
494				maxAttachSeq = n
495			}
496			if !filepath.IsAbs(a.Path) {
497				return fmt.Errorf("数据矛盾：附件记录 %s 的路径 %q 不是绝对路径", a.ID, a.Path)
498			}
499			t := tickets[a.TicketID]
500			if t == nil {
501				return fmt.Errorf("数据矛盾：附件记录 %s 引用了不存在的工单 %s", a.ID, a.TicketID)
502			}
503			if t.AssetID != a.AssetID {
504				return fmt.Errorf("数据矛盾：附件记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
505					a.ID, a.AssetID, t.ID, t.AssetID)
506			}
507			if a.Revoked && a.RevokeReason == "" {
508				return fmt.Errorf("状态矛盾：已撤销附件 %s 缺少撤销理由", a.ID)
509			}
510			if !a.Revoked && a.RevokeReason != "" {
511				return fmt.Errorf("状态矛盾：有效附件 %s 不应带有撤销理由", a.ID)
512			}
513			if attachments[a.ID] != nil {
514				return fmt.Errorf("数据矛盾：附件编号 %s 重复", a.ID)
515			}
516			attachments[a.ID] = a
517		}
518		// 下一附件序号必须为正并大于全部已用序号（允许有间隔）。
519		if d.NextAttachSeq < 1 || d.NextAttachSeq <= maxAttachSeq {
520			return fmt.Errorf("计数器矛盾：下一附件序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
521				d.NextAttachSeq, maxAttachSeq)
522		}
523		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
524		boundReq := map[string]bool{}
525		boundTicket := map[string]bool{}
526		for _, r := range d.Requests {
527			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
528				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
529			}
530			if boundReq[r.RequestID] {
531				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
532			}
533			boundReq[r.RequestID] = true
534			t := tickets[r.TicketID]
535			if t == nil {
536				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
537			}
538			if t.RequestID != r.RequestID {
539				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
540					r.TicketID, t.RequestID, r.RequestID)
541			}
542			if r.AssetID != t.AssetID || r.Description != t.Description {
543				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
544					r.RequestID, t.ID)
545			}
546			boundTicket[r.TicketID] = true
547		}
548		for _, t := range d.Tickets {
549			if !boundTicket[t.ID] {
550				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
551			}
552		}
553		// 状态：每项资产最多一张未关闭工单，有则必须为“维修中”；无未关闭工单时
554		// 资产可为“可用”或“停用”，停用与否由停用、恢复使用履历链决定，在下方
555		// 按履历序号重放时核对。
556		openCount := map[string]int{}
557		for _, t := range d.Tickets {
558			if t.Status == ticketOpen {
559				openCount[t.AssetID]++
560			}
561		}
562		for _, a := range d.Assets {
563			c := openCount[a.ID]
564			if c > 1 {
565				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
566			}
567			if c == 1 {
568				if a.Status != statusRepairing {
569					return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
570						a.ID, c, statusRepairing, a.Status)
571				}
572				continue
573			}
574			if a.Status != statusAvailable && a.Status != statusDeactivated {
575				return fmt.Errorf("状态矛盾：资产 %s 没有未关闭工单，状态应为 %s 或 %s，实际为 %s",
576					a.ID, statusAvailable, statusDeactivated, a.Status)
577			}
578		}
579		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
580		seenSeq := map[int]bool{}
581		reportSeq := map[string]int{}
582		closeSeq := map[string]int{}
583		cancelSeq := map[string]int{}
584		reportCount := map[string]int{}
585		closeCount := map[string]int{}
586		cancelCount := map[string]int{}
587		for i := range d.Events {
588			e := &d.Events[i]
589			if e.Seq < 1 {
590				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
591			}
592			if seenSeq[e.Seq] {
593				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
594			}
595			seenSeq[e.Seq] = true
596			if e.AssetID == "" || e.Kind == "" || e.Content == "" {
597				return errors.New("履历矛盾：存在字段不完整的履历记录")
598			}
599			if e.Kind == eventPlanCreate || e.Kind == eventPlanDone || e.Kind == eventPlanRevoke || e.Kind == eventPlanAdjust {
600				// 保养履历：不属于任何工单，不携带派工、备件或附件字段；日期与间隔在此
601				// 核对，建立、完成、撤销与调整链的接续在下方按序号重放时核对。
602				if e.TicketID != "" || e.From != "" || e.To != "" {
603					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号或派工人员字段", e.Seq, e.Kind)
604				}
605				if e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
606					e.AttachmentID != "" || e.Path != "" {
607					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件或附件字段", e.Seq, e.Kind)
608				}
609				if e.Kind != eventPlanAdjust &&
610					(e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "") {
611					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有方案调整字段", e.Seq, e.Kind)
612				}
613				if e.Kind == eventPlanAdjust {
614					// 调整履历：内容即调整理由（非空已检查）；Due/Interval 为新方案的
615					// 首次到期日与间隔天数，另携带原方案与调整前的下一到期日。
616					if e.Done != "" || e.TargetSeq != 0 {
617						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录不应带有完成日或目标完成履历序号", e.Seq)
618					}
619					if e.NewContent == "" {
620						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录缺少新保养内容", e.Seq)
621					}
622					if _, err := parseDate(e.Due); err != nil {
623						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录新首次到期日无效", e.Seq)
624					}
625					if e.Interval < 1 {
626						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录新间隔天数须为正整数", e.Seq)
627					}
628					if e.OldContent == "" {
629						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录缺少原保养内容", e.Seq)
630					}
631					if _, err := parseDate(e.OldDue); err != nil {
632						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原首次到期日无效", e.Seq)
633					}
634					if e.OldInterval < 1 {
635						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原间隔天数须为正整数", e.Seq)
636					}
637					if _, err := parseDate(e.OldNextDue); err != nil {
638						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原下一到期日无效", e.Seq)
639					}
640					continue
641				}
642				if e.Kind == eventPlanRevoke {
643					// 撤销履历：内容即撤销理由（非空已检查），仅携带目标完成履历序号。
644					if e.Due != "" || e.Done != "" || e.Interval != 0 {
645						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录不应带有到期日、完成日或间隔天数", e.Seq)
646					}
647					if e.TargetSeq < 1 {
648						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录目标完成履历序号须为正整数", e.Seq)
649					}
650					continue
651				}
652				if e.TargetSeq != 0 {
653					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有目标完成履历序号", e.Seq, e.Kind)
654				}
655				due, err := parseDate(e.Due)
656				if err != nil {
657					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录到期日无效", e.Seq, e.Kind)
658				}
659				if e.Kind == eventPlanCreate {
660					if e.Done != "" {
661						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录不应带有完成日", e.Seq)
662					}
663					if e.Interval < 1 {
664						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录间隔天数须为正整数", e.Seq)
665					}
666				} else {
667					if e.Interval != 0 {
668						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录不应带有间隔天数", e.Seq)
669					}
670					done, err := parseDate(e.Done)
671					if err != nil {
672						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录完成日无效", e.Seq)
673					}
674					if done < due {
675						return fmt.Errorf("履历矛盾：履历序号 %d 的完成日早于周期到期日", e.Seq)
676					}
677				}
678				continue
679			}
680			if e.Kind == eventDeactivate || e.Kind == eventReactivate {
681				// 停用/恢复使用为资产级履历：不属于任何工单，From/To 为原状态与新
682				// 状态，不携带派工、保养、备件或附件字段。转换是否接续（可用->停用、
683				// 停用->可用）在下方按履历序号重放时核对。
684				if e.TicketID != "" {
685					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号", e.Seq, e.Kind)
686				}
687				if e.From == "" || e.To == "" {
688					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少原状态或新状态", e.Seq, e.Kind)
689				}
690				if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 ||
691					e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "" ||
692					e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
693					e.AttachmentID != "" || e.Path != "" {
694					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有保养、备件或附件字段", e.Seq, e.Kind)
695				}
696				if assets[e.AssetID] == nil {
697					return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产", e.Seq)
698				}
699				continue
700			}
701			if e.TicketID == "" {
702				return errors.New("履历矛盾：存在字段不完整的履历记录")
703			}
704			if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 ||
705				e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "" {
706				return fmt.Errorf("履历矛盾：履历序号 %d 的维修履历不应带有保养字段", e.Seq)
707			}
708			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
709				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
710			}
711			if e.Kind == eventAssign {
712				if e.To == "" {
713					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
714				}
715				if e.From == e.To {
716					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
717				}
718			}
719			// 附件字段仅附件履历携带；附件履历不携带备件字段。
720			if e.Kind != eventAttach && e.Kind != eventAttachRevoke && (e.AttachmentID != "" || e.Path != "") {
721				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有附件编号或路径", e.Seq, e.Kind)
722			}
723			if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) &&
724				(e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "") {
725				return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件字段", e.Seq, e.Kind)
726			}
727			t := tickets[e.TicketID]
728			if t == nil || assets[e.AssetID] == nil {
729				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
730			}
731			if e.AssetID != t.AssetID {
732				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
733					e.Seq, e.AssetID, t.ID, t.AssetID)
734			}
735			switch e.Kind {
736			case eventReport:
737				if e.Content != t.Description {
738					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
739				}
740				reportCount[t.ID]++
741				reportSeq[t.ID] = e.Seq
742			case eventClose:
743				if e.Content != t.Result {
744					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
745				}
746				closeCount[t.ID]++
747				closeSeq[t.ID] = e.Seq
748			case eventCancel:
749				if e.Content != t.CancelReason {
750					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
751				}
752				cancelCount[t.ID]++
753				cancelSeq[t.ID] = e.Seq
754			case eventAssign:
755				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
756				// 在下方按序号重放时核对。
757			case eventPartWithdraw, eventPartReturn:
758				// 内容即领用说明或退回理由（非空已检查）；备件字段在此核对，
759				// 与领用记录的接续及累计退回在下方按序号重放时核对。
760				if e.PartID == "" || e.WithdrawalID == "" {
761					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少备件编号或领用编号", e.Seq, e.Kind)
762				}
763				if e.Quantity < 1 {
764					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录数量 %d 不是正整数", e.Seq, e.Kind, e.Quantity)
765				}
766				if _, ok := parsePartSeq(e.WithdrawalID); !ok {
767					return fmt.Errorf("履历矛盾：履历序号 %d 的领用编号 %q 不是 P 加补零正整数序号的形式",
768						e.Seq, e.WithdrawalID)
769				}
770			case eventAttach, eventAttachRevoke:
771				// 内容即附件说明或撤销理由（非空已检查）；附件字段在此核对，
772				// 与附件记录的接续及登记、撤销顺序在下方按序号重放时核对。
773				if e.AttachmentID == "" || e.Path == "" {
774					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少附件编号或路径", e.Seq, e.Kind)
775				}
776				if _, ok := parseAttachSeq(e.AttachmentID); !ok {
777					return fmt.Errorf("履历矛盾：履历序号 %d 的附件编号 %q 不是 A 加补零正整数序号的形式",
778						e.Seq, e.AttachmentID)
779				}
780				if !filepath.IsAbs(e.Path) {
781					return fmt.Errorf("履历矛盾：履历序号 %d 的附件路径 %q 不是绝对路径", e.Seq, e.Path)
782				}
783			default:
784				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
785			}
786		}
787		for _, t := range d.Tickets {
788			if reportCount[t.ID] != 1 {
789				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
790			}
791			if t.Status == ticketClosed {
792				if closeCount[t.ID] != 1 {
793					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
794				}
795				if closeSeq[t.ID] <= reportSeq[t.ID] {
796					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
797						t.ID, closeSeq[t.ID], reportSeq[t.ID])
798				}
799			} else if closeCount[t.ID] != 0 {
800				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
801			}
802			if t.Status == ticketCancelled {
803				if cancelCount[t.ID] != 1 {
804					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
805				}
806				if cancelSeq[t.ID] <= reportSeq[t.ID] {
807					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
808						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
809				}
810			} else if cancelCount[t.ID] != 0 {
811				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
812			}
813		}
814		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
815		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
816		sorted := make([]Event, len(d.Events))
817		copy(sorted, d.Events)
818		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
819		derivedTicket := map[string]string{}
820		derivedOpen := map[string]string{}
821		derivedDeactivated := map[string]bool{}
822		derivedAssignee := map[string]string{}
823		derivedNote := map[string]string{}
824		withdrawSeq := map[string]int{}
825		derivedReturned := map[string]int{}
826		attachRegSeq := map[string]int{}
827		attachRevokeSeq := map[string]int{}
828		for _, e := range sorted {
829			switch e.Kind {
830			case eventReport:
831				if derivedTicket[e.TicketID] != "" {
832					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
833				}
834				if prev := derivedOpen[e.AssetID]; prev != "" {
