846				// 工单）的资产不能停用。From/To 须与实际转换一致。
847				if derivedOpen[e.AssetID] != "" {
848					return fmt.Errorf("履历矛盾：资产 %s 在存在未关闭工单时出现停用履历（序号 %d）",
849						e.AssetID, e.Seq)
850				}
851				if derivedDeactivated[e.AssetID] {
852					return fmt.Errorf("履历矛盾：资产 %s 被重复停用（序号 %d）", e.AssetID, e.Seq)
853				}
854				if e.From != statusAvailable || e.To != statusDeactivated {
855					return fmt.Errorf("履历矛盾：停用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
856						e.Seq, statusAvailable, statusDeactivated, e.From, e.To)
857				}
858				derivedDeactivated[e.AssetID] = true
859			case eventReactivate:
860				// 恢复使用只作用于停用资产；From/To 须与实际转换一致。
861				if !derivedDeactivated[e.AssetID] {
862					return fmt.Errorf("履历矛盾：资产 %s 未停用却出现恢复使用履历（序号 %d）", e.AssetID, e.Seq)
863				}
864				if derivedOpen[e.AssetID] != "" {
865					return fmt.Errorf("履历矛盾：资产 %s 恢复使用（序号 %d）时仍存在未关闭工单",
866						e.AssetID, e.Seq)
867				}
868				if e.From != statusDeactivated || e.To != statusAvailable {
869					return fmt.Errorf("履历矛盾：恢复使用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
870						e.Seq, statusDeactivated, statusAvailable, e.From, e.To)
871				}
872				delete(derivedDeactivated, e.AssetID)
873			case eventAssign:
874				if derivedTicket[e.TicketID] != ticketOpen {
