1037		plans := map[string]*Plan{}
1038		for _, p := range d.Plans {
1039			if p == nil || p.AssetID == "" || p.Content == "" {
1040				return errors.New("数据矛盾：存在字段不完整的保养计划")
1041			}
1042			if assets[p.AssetID] == nil {
1043				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
1044			}
1045			if plans[p.AssetID] != nil {
1046				return fmt.Errorf("数据矛盾：资产 %s 有多个保养计划，最多允许一个", p.AssetID)
1047			}
1048			if _, err := parseDate(p.FirstDue); err != nil {
1049				return fmt.Errorf("数据矛盾：资产 %s 保养计划的首次到期日无效", p.AssetID)
1050			}
1051			if p.IntervalDays < 1 {
