22	// 建立计划：成功、重复拒绝、未知资产拒绝、非法输入拒绝；详情与履历输出。
23	func TestPlanCreateAndDetail(t *testing.T) {
24		s := newTestStore(t)
25		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
26			t.Fatal(err)
27		}
28	
29		// 未知资产拒绝。
30		if _, err := s.createPlan("NOPE", "更换滤芯", "2026-11-01", 90); !errors.Is(err, errNotFound) {
31			t.Fatalf("未知资产应失败，得到 %v", err)
32		}
33		// 非法输入拒绝：空内容、非正间隔、无效日期。
34		if _, err := s.createPlan("EQ-1", "", "2026-11-01", 90); !errors.Is(err, errConflict) {
35			t.Fatalf("空内容应失败，得到 %v", err)
36		}
37		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-11-01", 0); !errors.Is(err, errConflict) {
38			t.Fatalf("零间隔应失败，得到 %v", err)
39		}
40		for _, bad := range []string{"2026-1-1", "2026-13-01", "2026-02-29", "0000-01-01", "20261101"} {
41			if _, err := s.createPlan("EQ-1", "更换滤芯", bad, 90); !errors.Is(err, errConflict) {
42				t.Fatalf("日期 %q 应失败，得到 %v", bad, err)
43			}
44		}
45		if len(s.data.Plans) != 0 || len(s.data.Events) != 0 {
46			t.Fatal("失败的建立不应产生计划或履历")
47		}
48	
49		p, err := s.createPlan("EQ-1", "更换滤芯", "2026-11-01", 90)
50		if err != nil {
51			t.Fatalf("createPlan: %v", err)
52		}
53		if p.NextDue != "2026-11-01" {
54			t.Fatalf("下一到期日 = %q，想得到 2026-11-01", p.NextDue)
55		}
56		// 已有计划拒绝，不覆盖。
57		if _, err := s.createPlan("EQ-1", "其他内容", "2027-01-01", 30); !errors.Is(err, errConflict) {
58			t.Fatalf("重复建立应冲突，得到 %v", err)
59		}
60		if got := s.findPlan("EQ-1"); got.Content != "更换滤芯" || got.IntervalDays != 90 {
61			t.Fatalf("计划不应被覆盖: %+v", got)
62		}
63		// 恰一条建立履历，含初始计划。
64		events := s.eventsOf("EQ-1")
65		if len(events) != 1 || events[0].Kind != eventPlanCreate ||
66			events[0].Content != "更换滤芯" || events[0].Due != "2026-11-01" || events[0].Interval != 90 {
67			t.Fatalf("建立履历不对: %+v", events)
