69	
70		// 重启后保持；详情显示计划。
71		s = saveAndReopen(t, s)
72		if got := s.findPlan("EQ-1"); got == nil || got.NextDue != "2026-11-01" {
73			t.Fatalf("重开后计划未保持: %+v", got)
74		}
75		var buf bytes.Buffer
76		if err := cmdDetail([]string{"--data-dir", s.dir, "--asset-id", "EQ-1"}, &buf); err != nil {
77			t.Fatal(err)
78		}
79		out := buf.String()
80		for _, want := range []string{"保养内容: 更换滤芯", "保养间隔: 每 90 天", "下一到期日: 2026-11-01"} {
81			if !strings.Contains(out, want) {
82				t.Fatalf("详情缺少 %q:\n%s", want, out)
83			}
84		}
85		// 无计划资产明确提示。
86		if _, err := s.registerAsset("EQ-2", "空调", "二楼"); err != nil {
87			t.Fatal(err)
88		}
89		if err := s.save(); err != nil {
90			t.Fatal(err)
91		}
92		buf.Reset()
93		if err := cmdDetail([]string{"--data-dir", s.dir, "--asset-id", "EQ-2"}, &buf); err != nil {
