101	// 延期完成：跨过的周期不生成记录，下一到期日为首次到期日加整数倍间隔中
102	// 严格晚于完成日的最早日期，而不是完成日加间隔。
103	func TestCompleteDelayedSkipsCycles(t *testing.T) {
104		s := newTestStore(t)
105		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
106			t.Fatal(err)
107		}
108		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-01-01", 10); err != nil {
109			t.Fatal(err)
110		}
111		// 到期日 2026-01-01，延期到 2026-01-25 完成：跨过 01-11、01-21 两个周期，
112		// 下一到期日为 01-31（首次+3*10），而非 01-25+10=02-04。
113		p, next, _, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-25", "已更换")
114		if err != nil {
115			t.Fatalf("completePlan: %v", err)
116		}
117		if next != "2026-01-31" || p.NextDue != "2026-01-31" {
118			t.Fatalf("下一到期日 = %q，想得到 2026-01-31", next)
119		}
120		// 只记录一次实际保养：建立 + 完成共两条履历。
121		events := s.eventsOf("EQ-1")
122		if len(events) != 2 || events[1].Kind != eventPlanDone ||
123			events[1].Due != "2026-01-01" || events[1].Done != "2026-01-25" || events[1].Content != "已更换" {
124			t.Fatalf("完成履历不对: %+v", events)
125		}
126		// 重启后保持。
127		s = saveAndReopen(t, s)
128		if got := s.findPlan("EQ-1"); got.NextDue != "2026-01-31" {
129			t.Fatalf("重开后下一到期日 = %q", got.NextDue)
130		}
131	}
