133	// 旧周期重复登记与登记新周期均拒绝；完成日早于到期日拒绝；空结果拒绝。
134	func TestCompleteOldCycleRepeatRejected(t *testing.T) {
135		s := newTestStore(t)
136		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
137			t.Fatal(err)
138		}
139		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-01-01", 10); err != nil {
140			t.Fatal(err)
141		}
142		// 无计划资产拒绝。
143		if _, err := s.registerAsset("EQ-2", "空调", "二楼"); err != nil {
144			t.Fatal(err)
145		}
146		if _, _, _, err := s.completePlan("EQ-2", "2026-01-01", "2026-01-01", "结果"); !errors.Is(err, errNotFound) {
147			t.Fatalf("无计划应失败，得到 %v", err)
148		}
149		// 完成日早于到期日拒绝。
150		if _, _, _, err := s.completePlan("EQ-1", "2026-01-01", "2025-12-31", "结果"); !errors.Is(err, errConflict) {
151			t.Fatalf("完成日早于到期日应失败，得到 %v", err)
152		}
153		// 空结果拒绝。
154		if _, _, _, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-01", ""); !errors.Is(err, errConflict) {
155			t.Fatalf("空结果应失败，得到 %v", err)
156		}
157		// 尚未到期的新周期不能登记。
158		if _, _, _, err := s.completePlan("EQ-1", "2026-01-11", "2026-01-11", "结果"); !errors.Is(err, errConflict) {
159			t.Fatalf("登记新周期应失败，得到 %v", err)
160		}
161	
162		// 正常完成两个周期：01-01 当天完成 → 下一 01-11；01-11 当天完成 → 下一 01-21。
163		if _, next, _, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-01", "第一次"); err != nil || next != "2026-01-11" {
164			t.Fatalf("第一周期: next=%q err=%v", next, err)
165		}
166		if _, next, _, err := s.completePlan("EQ-1", "2026-01-11", "2026-01-11", "第二次"); err != nil || next != "2026-01-21" {
167			t.Fatalf("第二周期: next=%q err=%v", next, err)
168		}
169		// 旧周期重复登记拒绝，状态不推进。
170		for _, due := range []string{"2026-01-01", "2026-01-11"} {
171			if _, _, _, err := s.completePlan("EQ-1", due, "2026-01-21", "重复"); !errors.Is(err, errConflict) {
172				t.Fatalf("旧周期 %s 重复应失败，得到 %v", due, err)
173			}
174		}
175		if got := s.findPlan("EQ-1"); got.NextDue != "2026-01-21" {
176			t.Fatalf("失败的重复登记不应推进日期，下一到期日 = %q", got.NextDue)
177		}
178		if got := len(s.eventsOf("EQ-1")); got != 3 {
179			t.Fatalf("失败的重复登记不应新增履历，履历数 = %d", got)
180		}
181	}
