183	// 闰日按公历规则运算：2024 为闰年，2025、2100 不是。
184	func TestLeapDayArithmetic(t *testing.T) {
185		s := newTestStore(t)
186		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
187			t.Fatal(err)
188		}
189		// 2024-02-29 是有效日期；间隔 365 天，下一到期为 2025-02-28
190		// （2024-02-29 + 365 个日历日；2024-03-01 至 2025-02-28 共 365 天）。
191		if _, err := s.createPlan("EQ-1", "年检", "2024-02-29", 365); err != nil {
192			t.Fatal(err)
193		}
194		if _, next, _, err := s.completePlan("EQ-1", "2024-02-29", "2024-02-29", "完成"); err != nil || next != "2025-02-28" {
195			t.Fatalf("闰日完成: next=%q err=%v", next, err)
196		}
197		// 2025-02-29 无效（平年）。
198		if _, err := s.registerAsset("EQ-2", "空调", "二楼"); err != nil {
199			t.Fatal(err)
200		}
201		if _, err := s.createPlan("EQ-2", "年检", "2025-02-29", 365); !errors.Is(err, errConflict) {
202			t.Fatalf("平年 2 月 29 日应拒绝，得到 %v", err)
203		}
204		// 间隔 1 天跨闰日：2024-02-28 完成 → 下一 2024-02-29。
205		if _, err := s.createPlan("EQ-2", "日检", "2024-02-28", 1); err != nil {
206			t.Fatal(err)
207		}
208		if _, next, _, err := s.completePlan("EQ-2", "2024-02-28", "2024-02-28", "完成"); err != nil || next != "2024-02-29" {
209			t.Fatalf("跨闰日: next=%q err=%v", next, err)
210		}
211		// 2100 年不是闰年：2100-02-28 + 1 = 2100-03-01。
212		if _, err := s.registerAsset("EQ-3", "叉车", "仓库"); err != nil {
213			t.Fatal(err)
214		}
215		if _, err := s.createPlan("EQ-3", "日检", "2100-02-28", 1); err != nil {
216			t.Fatal(err)
217		}
218		if _, next, _, err := s.completePlan("EQ-3", "2100-02-28", "2100-02-28", "完成"); err != nil || next != "2100-03-01" {
219			t.Fatalf("2100 非闰年: next=%q err=%v", next, err)
220		}
221		// 延期跨过闰日：2024-02-28 到期、间隔 1、2024-03-01 完成 → 下一 2024-03-02。
222		if _, err := s.registerAsset("EQ-4", "饮水机", "四楼"); err != nil {
223			t.Fatal(err)
224		}
225		if _, err := s.createPlan("EQ-4", "日检", "2024-02-27", 1); err != nil {
226			t.Fatal(err)
227		}
228		if _, next, _, err := s.completePlan("EQ-4", "2024-02-27", "2024-03-01", "完成"); err != nil || next != "2024-03-02" {
229			t.Fatalf("延期跨闰日: next=%q err=%v", next, err)
230		}
231	}
