233	// 无保养字段的有效旧库直接加载，可建立计划并完成，重启后保持。
234	func TestLegacyStoreWithoutPlansField(t *testing.T) {
235		dir := t.TempDir()
236		writeLedger(t, dir, nil) // baseLedger 无 plans 字段
237		s, err := openStore(dir)
238		if err != nil {
239			t.Fatalf("无保养字段的旧库应能加载: %v", err)
240		}
241		if len(s.data.Plans) != 0 {
242			t.Fatal("旧库不应有保养计划")
243		}
244		s.now = newTestStore(t).now
245		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-11-01", 90); err != nil {
246			t.Fatalf("旧库建立计划: %v", err)
247		}
248		if _, next, _, err := s.completePlan("EQ-1", "2026-11-01", "2026-11-02", "已更换"); err != nil {
249			t.Fatalf("旧库完成登记: %v", err)
250		} else if next != "2027-01-30" {
251			t.Fatalf("下一到期日 = %q，想得到 2027-01-30", next)
252		}
253		if err := s.save(); err != nil {
254			t.Fatal(err)
255		}
256		s2, err := openStore(dir)
257		if err != nil {
258			t.Fatal(err)
259		}
260		if got := s2.findPlan("EQ-1"); got == nil || got.NextDue != "2027-01-30" {
261			t.Fatalf("重开后计划未保持: %+v", got)
262		}
263		// 旧工单行为保持：未关闭工单仍在，资产仍为维修中。
264		if got := s2.openTicketOf("EQ-1"); got == nil || got.ID != "T0001" {
265			t.Fatalf("旧库工单应保持，得到 %v", got)
266		}
267		if got := s2.findAsset("EQ-1").Status; got != statusRepairing {
268			t.Fatalf("资产状态 = %q", got)
269		}
