272	// 维修中资产可建立计划并登记完成：不创建或终结工单、不消耗工单编号，
273	// 不改变资产状态、请求绑定或停机统计；履历按序号交错展示。
274	func TestMaintenanceInterleavedWithRepair(t *testing.T) {
275		s := newTestStore(t)
276		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
277			t.Fatal(err)
278		}
279		tk, _, err := s.report("EQ-1", "卡纸", "req-1")
280		if err != nil {
281			t.Fatal(err)
282		}
283		// 维修中建立计划、登记完成。
284		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-11-01", 90); err != nil {
285			t.Fatalf("维修中建立计划: %v", err)
286		}
287		if _, _, _, err := s.completePlan("EQ-1", "2026-11-01", "2026-11-02", "已更换"); err != nil {
288			t.Fatalf("维修中登记完成: %v", err)
289		}
290		// 资产状态、工单、编号计数器、请求绑定均不变。
291		if got := s.findAsset("EQ-1").Status; got != statusRepairing {
292			t.Fatalf("保养不应改变资产状态，得到 %q", got)
293		}
294		if len(s.data.Tickets) != 1 || s.data.Tickets[0].Status != ticketOpen {
295			t.Fatalf("保养不应创建或终结工单: %+v", s.data.Tickets)
296		}
297		if s.data.NextTicketSeq != 2 {
298			t.Fatalf("保养不应消耗工单编号，NextTicketSeq = %d", s.data.NextTicketSeq)
299		}
300		if len(s.data.Requests) != 1 {
301			t.Fatalf("保养不应改变请求绑定，绑定数 = %d", len(s.data.Requests))
302		}
303		// 履历交错：报修、保养建立、保养完成，按序号排列。
304		events := s.eventsOf("EQ-1")
305		if len(events) != 3 || events[0].Kind != eventReport ||
306			events[1].Kind != eventPlanCreate || events[2].Kind != eventPlanDone {
307			t.Fatalf("履历顺序不对: %+v", events)
308		}
309		// 关闭工单后保养行为不变。
310		if _, _, err := s.closeTicket(tk.ID, "已修复"); err != nil {
311			t.Fatal(err)
312		}
313		if _, next, _, err := s.completePlan("EQ-1", "2027-01-30", "2027-01-30", "第二次"); err != nil || next != "2027-04-30" {
314			t.Fatalf("关闭后登记完成: next=%q err=%v", next, err)
315		}
316		if got := s.findAsset("EQ-1").Status; got != statusAvailable {
317			t.Fatalf("资产状态 = %q", got)
318		}
319		// 停机统计不受保养履历影响（履历时间由测试时钟产生，窗口覆盖即可）。
320		s = saveAndReopen(t, s)
321		start := mustParseTime(t, "2020-01-01T00:00:00Z")
322		end := mustParseTime(t, "2030-12-31T00:00:00Z")
323		res, err := s.downtimeForAssets([]string{"EQ-1"}, start, end)
324		if err != nil {
325			t.Fatal(err)
326		}
327		events = s.eventsOf("EQ-1")
328		var reportTime, closeTime int64
329		for _, e := range events {
330			switch e.Kind {
331			case eventReport:
332				reportTime = e.Time.Unix()
333			case eventClose:
334				closeTime = e.Time.Unix()
335			}
336		}
337		if res[0].Seconds != closeTime-reportTime {
338			t.Fatalf("停机秒数 = %d，想得到 %d（保养履历不应计入）", res[0].Seconds, closeTime-reportTime)
339		}
340		// history 输出包含保养履历。
341		var buf bytes.Buffer
342		if err := cmdHistory([]string{"--data-dir", s.dir, "--asset-id", "EQ-1"}, &buf); err != nil {
343			t.Fatal(err)
344		}
345		out := buf.String()
346		for _, want := range []string{"保养建立", "保养完成", "周期到期日 2026-11-01，实际完成日 2026-11-02"} {
347			if !strings.Contains(out, want) {
348				t.Fatalf("履历输出缺少 %q:\n%s", want, out)
349			}
350		}
351	}
