353	// 到期查询：按到期日再按资产编号排序，无匹配明确提示，只读不初始化目录。
354	func TestDueQuery(t *testing.T) {
355		s := newTestStore(t)
356		for _, a := range [][3]string{
357			{"EQ-B", "空调", "二楼"}, {"EQ-A", "打印机", "一楼"}, {"EQ-C", "叉车", "仓库"},
358		} {
359			if _, err := s.registerAsset(a[0], a[1], a[2]); err != nil {
360				t.Fatal(err)
361			}
362		}
363		// EQ-A 与 EQ-B 同一到期日（检验按编号次序），EQ-C 更晚。
364		if _, err := s.createPlan("EQ-B", "清洗", "2026-11-01", 30); err != nil {
365			t.Fatal(err)
366		}
367		if _, err := s.createPlan("EQ-A", "更换滤芯", "2026-11-01", 90); err != nil {
368			t.Fatal(err)
369		}
370		if _, err := s.createPlan("EQ-C", "润滑", "2026-12-01", 60); err != nil {
371			t.Fatal(err)
372		}
373		if err := s.save(); err != nil {
374			t.Fatal(err)
375		}
376	
377		var buf bytes.Buffer
378		if err := cmdDue([]string{"--data-dir", s.dir, "--date", "2026-11-15"}, &buf); err != nil {
379			t.Fatal(err)
380		}
381		out := buf.String()
382		lines := strings.Split(strings.TrimSpace(out), "\n")
383		if len(lines) != 3 { // 表头 + 两行
384			t.Fatalf("输出应为 3 行:\n%s", out)
385		}
386		if !strings.Contains(lines[1], "EQ-A\t打印机\t更换滤芯\t2026-11-01") ||
387			!strings.Contains(lines[2], "EQ-B\t空调\t清洗\t2026-11-01") {
388			t.Fatalf("同到期日应按资产编号排序:\n%s", out)
389		}
390		// 更晚的截止日包含全部，EQ-C 排在最后。
391		buf.Reset()
392		if err := cmdDue([]string{"--data-dir", s.dir, "--date", "2026-12-31"}, &buf); err != nil {
393			t.Fatal(err)
394		}
395		out = buf.String()
396		if !strings.Contains(out, "共 3 项") || strings.Index(out, "EQ-C") < strings.Index(out, "EQ-B") {
397			t.Fatalf("排序或数量不对:\n%s", out)
398		}
399		// 无匹配明确提示。
400		buf.Reset()
401		if err := cmdDue([]string{"--data-dir", s.dir, "--date", "2026-10-01"}, &buf); err != nil {
402			t.Fatal(err)
403		}
404		if !strings.Contains(buf.String(), "没有到期的保养计划") {
405			t.Fatalf("无匹配应明确提示:\n%s", buf.String())
406		}
407		// 只读：目录不存在时不初始化目录、不写文件。
408		missing := filepath.Join(t.TempDir(), "no-such-dir")
409		buf.Reset()
410		if err := cmdDue([]string{"--data-dir", missing, "--date", "2026-12-31"}, &buf); err != nil {
411			t.Fatal(err)
412		}
413		if !strings.Contains(buf.String(), "没有到期的保养计划") {
414			t.Fatalf("空库应明确提示:\n%s", buf.String())
415		}
416		if _, err := os.Stat(missing); !os.IsNotExist(err) {
417			t.Fatalf("查询不应初始化目录: %v", err)
418		}
419		// 查询不推进计划。
420		if got := s.findPlan("EQ-A"); got.NextDue != "2026-11-01" {
421			t.Fatalf("查询不应推进计划，下一到期日 = %q", got.NextDue)
422		}
423	}
424	
425	// 导入复制保养计划与保养履历，完成链接续；目标已有计划不变；源只读。
426	func TestImportCopiesPlans(t *testing.T) {
427		srcDir := filepath.Join(t.TempDir(), "src")
428		dstDir := filepath.Join(t.TempDir(), "dst")
429	
430		src := newStoreAt(t, srcDir)
431		for _, a := range [][3]string{{"EQ-A", "打印机", "一楼"}, {"EQ-B", "空调", "二楼"}} {
432			if _, err := src.registerAsset(a[0], a[1], a[2]); err != nil {
433				t.Fatal(err)
434			}
435		}
436		if _, err := src.createPlan("EQ-A", "更换滤芯", "2026-01-01", 10); err != nil {
437			t.Fatal(err)
438		}
439		if _, _, _, err := src.completePlan("EQ-A", "2026-01-01", "2026-01-25", "已更换"); err != nil {
440			t.Fatal(err)
441		}
442		if _, _, err := src.report("EQ-A", "卡纸", "req-a1"); err != nil {
443			t.Fatal(err)
444		}
445		if _, err := src.createPlan("EQ-B", "清洗", "2026-06-01", 30); err != nil {
446			t.Fatal(err)
447		}
448		mustSave(t, src)
449	
450		// 目标已有自己的计划，导入后不变。
451		dst := newStoreAt(t, dstDir)
452		if _, err := dst.registerAsset("EQ-X", "叉车", "仓库"); err != nil {
453			t.Fatal(err)
454		}
455		if _, err := dst.createPlan("EQ-X", "润滑", "2026-05-01", 60); err != nil {
456			t.Fatal(err)
457		}
458		mustSave(t, dst)
459	
460		srcBefore := readFileBytes(t, srcDir)
461		outcome, err := importAssets(dstDir, srcDir, []string{"EQ-A"})
462		if err != nil {
463			t.Fatalf("导入失败: %v", err)
464		}
465		if outcome.plans != 1 {
466			t.Fatalf("应导入 1 项计划，得到 %d", outcome.plans)
467		}
468		if got := readFileBytes(t, srcDir); !bytes.Equal(got, srcBefore) {
469			t.Fatal("源台账应保持只读不变")
470		}
471	
472		// 目标：EQ-A 计划原样复制（下一到期日 2026-01-31），EQ-X 计划不变。
473		re, err := openStore(dstDir)
474		if err != nil {
475			t.Fatal(err)
476		}
477		pa := re.findPlan("EQ-A")
478		if pa == nil || pa.Content != "更换滤芯" || pa.FirstDue != "2026-01-01" ||
479			pa.IntervalDays != 10 || pa.NextDue != "2026-01-31" {
480			t.Fatalf("导入的计划不对: %+v", pa)
481		}
482		if px := re.findPlan("EQ-X"); px == nil || px.NextDue != "2026-05-01" {
483			t.Fatalf("目标已有计划不应改变: %+v", px)
484		}
485		if re.findPlan("EQ-B") != nil {
486			t.Fatal("未选择的资产不应导入计划")
487		}
488		// 完成链接续：可在目标继续登记下一周期。
489		if _, next, _, err := re.completePlan("EQ-A", "2026-01-31", "2026-01-31", "目标完成"); err != nil || next != "2026-02-10" {
490			t.Fatalf("导入后完成链接续: next=%q err=%v", next, err)
491		}
492		mustSave(t, re)
493		// 重启后保持。
494		re2, err := openStore(dstDir)
495		if err != nil {
496			t.Fatal(err)
497		}
498		if got := re2.findPlan("EQ-A"); got.NextDue != "2026-02-10" {
499			t.Fatalf("重启后下一到期日 = %q", got.NextDue)
500		}
501		// 保养履历随资产导入：EQ-A 的建立与完成履历齐全。
502		var creates, dones int
503		for _, e := range re2.eventsOf("EQ-A") {
504			switch e.Kind {
505			case eventPlanCreate:
506				creates++
507			case eventPlanDone:
508				dones++
509			}
510		}
511		if creates != 1 || dones != 2 {
512			t.Fatalf("保养履历条数不对: 建立 %d 完成 %d", creates, dones)
513		}
514	}
515	
516	// 下一到期日超出日期范围时整次拒绝：不推进日期、不新增履历，原文件不变，
517	// 恢复（改用更早完成日）后可重试。
518	func TestCompleteOverflowRejectedAndRetry(t *testing.T) {
519		s := newTestStore(t)
520		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
521			t.Fatal(err)
522		}
523		// 9999-01-01 + 364 天 = 9999-12-31（范围内）；再推进即超出 9999-12-31。
524		if _, err := s.createPlan("EQ-1", "年检", "9999-01-01", 364); err != nil {
525			t.Fatal(err)
526		}
527		if err := s.save(); err != nil {
528			t.Fatal(err)
529		}
530		before := readFileBytes(t, s.dir)
531	
532		// 完成日 9999-12-31：下一到期日须严格晚于它，即 9999-01-01+728 天，越界。
533		if _, _, _, err := s.completePlan("EQ-1", "9999-01-01", "9999-12-31", "完成"); !errors.Is(err, errConflict) {
534			t.Fatalf("下一到期日越界应整次拒绝，得到 %v", err)
535		}
536		// 不推进日期、不新增履历。
537		if got := s.findPlan("EQ-1"); got.NextDue != "9999-01-01" {
538			t.Fatalf("拒绝后不应推进日期，下一到期日 = %q", got.NextDue)
539		}
540		if got := len(s.eventsOf("EQ-1")); got != 1 {
541			t.Fatalf("拒绝后不应新增履历，履历数 = %d", got)
542		}
543		// 原文件字节不变。
544		if got := readFileBytes(t, s.dir); !bytes.Equal(got, before) {
545			t.Fatal("拒绝后原文件不应改变")
546		}
547		// 重载后状态保持，可用更早完成日重试成功。
548		s = saveAndReopen(t, s)
549		if _, next, _, err := s.completePlan("EQ-1", "9999-01-01", "9999-01-01", "完成"); err != nil || next != "9999-12-31" {
550			t.Fatalf("重试应成功: next=%q err=%v", next, err)
551		}
552		if err := s.save(); err != nil {
553			t.Fatal(err)
554		}
555		s = saveAndReopen(t, s)
556		if got := s.findPlan("EQ-1"); got.NextDue != "9999-12-31" {
557			t.Fatalf("重载后下一到期日 = %q", got.NextDue)
558		}
559		// 到达范围尽头后，再次完成必然越界，整次拒绝。
560		if _, _, _, err := s.completePlan("EQ-1", "9999-12-31", "9999-12-31", "完成"); !errors.Is(err, errConflict) {
561			t.Fatalf("范围尽头完成应拒绝，得到 %v", err)
562		}
563	}
564	
565	// 矛盾保养数据（计划归属、唯一性、日期、建立及完成链、推出日期）加载即报错，
566	// 不自动修复，原文件保留。
567	func TestPlanConsistencyRejected(t *testing.T) {
568		// 在 baseLedger 基础上附加合法的保养数据，再分别破坏。
569		basePlan := func(m map[string]any) {
570			m["plans"] = []any{map[string]any{
571				"asset_id": "EQ-1", "content": "更换滤芯",
572				"first_due": "2026-11-01", "interval_days": 90, "next_due": "2026-11-01",
573			}}
574			appendTo(m, "events", map[string]any{
575				"seq": 4, "asset_id": "EQ-1", "kind": "保养建立", "content": "更换滤芯",
576				"due": "2026-11-01", "interval": 90, "time": "2026-10-01T12:00:00Z",
577			})
578		}
579		cases := map[string]func(m map[string]any){
580			"计划引用不存在的资产": func(m map[string]any) {
581				basePlan(m)
582				m["plans"].([]any)[0].(map[string]any)["asset_id"] = "EQ-X"
583			},
584			"同一资产两个计划": func(m map[string]any) {
585				basePlan(m)
586				m["plans"] = append(m["plans"].([]any), map[string]any{
587					"asset_id": "EQ-1", "content": "另一个",
588					"first_due": "2026-11-01", "interval_days": 90, "next_due": "2026-11-01",
589				})
590			},
591			"首次到期日无效": func(m map[string]any) {
592				basePlan(m)
593				m["plans"].([]any)[0].(map[string]any)["first_due"] = "2026-02-29"
594			},
595			"间隔非正整数": func(m map[string]any) {
596				basePlan(m)
597				m["plans"].([]any)[0].(map[string]any)["interval_days"] = 0
598			},
599			"缺少建立履历": func(m map[string]any) {
600				m["plans"] = []any{map[string]any{
601					"asset_id": "EQ-1", "content": "更换滤芯",
602					"first_due": "2026-11-01", "interval_days": 90, "next_due": "2026-11-01",
603				}}
604			},
605			"建立履历与计划不符": func(m map[string]any) {
606				basePlan(m)
607				m["plans"].([]any)[0].(map[string]any)["content"] = "其他内容"
608			},
609			"完成链接续断裂": func(m map[string]any) {
610				basePlan(m)
611				appendTo(m, "events", map[string]any{
612					"seq": 5, "asset_id": "EQ-1", "kind": "保养完成", "content": "已更换",
613					"due": "2026-11-02", "done": "2026-11-02", "time": "2026-10-01T13:00:00Z",
614				})
615				m["plans"].([]any)[0].(map[string]any)["next_due"] = "2027-01-31"
616			},
617			"推出日期与保存不符": func(m map[string]any) {
618				basePlan(m)
619				appendTo(m, "events", map[string]any{
620					"seq": 5, "asset_id": "EQ-1", "kind": "保养完成", "content": "已更换",
621					"due": "2026-11-01", "done": "2026-11-02", "time": "2026-10-01T13:00:00Z",
622				})
623				m["plans"].([]any)[0].(map[string]any)["next_due"] = "2026-11-01"
624			},
625			"无计划却有保养履历": func(m map[string]any) {
626				appendTo(m, "events", map[string]any{
627					"seq": 4, "asset_id": "EQ-1", "kind": "保养建立", "content": "更换滤芯",
628					"due": "2026-11-01", "interval": 90, "time": "2026-10-01T12:00:00Z",
629				})
630			},
631		}
632		for name, mutate := range cases {
633			t.Run(name, func(t *testing.T) {
634				dir := t.TempDir()
635				raw := writeLedger(t, dir, mutate)
636				if _, err := openStore(dir); err == nil {
637					t.Fatal("矛盾数据应报错")
638				} else if !strings.Contains(err.Error(), "矛盾") {
639					t.Fatalf("错误应指出矛盾，得到 %v", err)
640				}
641				// 原文件保留，不自动修复。
642				if got := readFileBytes(t, dir); !bytes.Equal(got, raw) {
643					t.Fatal("原文件不应被修改")
644				}
645			})
646		}
647		// 合法的保养数据可以加载。
648		dir := t.TempDir()
649		writeLedger(t, dir, basePlan)
650		s, err := openStore(dir)
651		if err != nil {
652			t.Fatalf("合法保养数据应能加载: %v", err)
653		}
654		if got := s.findPlan("EQ-1"); got == nil || got.NextDue != "2026-11-01" {
655			t.Fatalf("计划未加载: %+v", got)
656		}
657	}
658	
659	// 参数错误退出码 2，业务失败退出码 1。
660	func TestMaintenanceExitCodes(t *testing.T) {
661		dir := t.TempDir()
662		var out, errOut bytes.Buffer
663		// 缺少必填参数、非法日期、非正间隔 → 2。
664		for _, args := range [][]string{
665			{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2026-11-01"},
666			{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2026-13-01", "--interval-days", "90"},
667			{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2026-11-01", "--interval-days", "-3"},
668			{"maintain", "--data-dir", dir, "--asset-id", "EQ-1", "--due", "bad", "--done", "2026-11-01", "--result", "x"},
669			{"due", "--data-dir", dir, "--date", "2026-1-1"},
670		} {
671			out.Reset()
672			errOut.Reset()
673			if code := run(args, &out, &errOut); code != 2 {
674				t.Fatalf("参数错误应退出 2: %v → %d (%s)", args, code, errOut.String())
675			}
676		}
677		// 未知资产 → 1。
678		out.Reset()
679		errOut.Reset()
680		code := run([]string{"plan", "--data-dir", dir, "--asset-id", "NOPE", "--content", "x",
681			"--first-due", "2026-11-01", "--interval-days", "90"}, &out, &errOut)
682		if code != 1 {
683			t.Fatalf("业务失败应退出 1，得到 %d", code)
684		}
685		// 建立后重复建立 → 1；成功 → 0。
686		out.Reset()
687		errOut.Reset()
688		code = run([]string{"register", "--data-dir", dir, "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼"}, &out, &errOut)
689		if code != 0 {
690			t.Fatalf("register: %d %s", code, errOut.String())
691		}
692		out.Reset()
693		errOut.Reset()
694		code = run([]string{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "更换滤芯",
695			"--first-due", "2026-11-01", "--interval-days", "90"}, &out, &errOut)
696		if code != 0 || !strings.Contains(out.String(), "首次到期日: 2026-11-01") {
697			t.Fatalf("plan 应成功并显示首次到期日: %d %s %s", code, out.String(), errOut.String())
698		}
699		out.Reset()
700		errOut.Reset()
701		code = run([]string{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "覆盖",
702			"--first-due", "2027-01-01", "--interval-days", "30"}, &out, &errOut)
703		if code != 1 {
704			t.Fatalf("重复建立应退出 1，得到 %d", code)
705		}
706		// 完成登记成功输出完成周期与下一到期日。
707		out.Reset()
708		errOut.Reset()
709		code = run([]string{"maintain", "--data-dir", dir, "--asset-id", "EQ-1",
710			"--due", "2026-11-01", "--done", "2026-11-03", "--result", "已更换"}, &out, &errOut)
711		if code != 0 || !strings.Contains(out.String(), "已完成周期 2026-11-01") ||
712			!strings.Contains(out.String(), "下一到期日: 2027-01-30") {
713			t.Fatalf("maintain 输出不对: %d %s %s", code, out.String(), errOut.String())
714		}
715	}
