193			t.Fatalf("撤销最新完成: %v", err)
194		}
195		if p.NextDue != "2026-04-02" || target.Due != "2026-04-02" {
196			t.Fatalf("恢复下一到期日 = %q，想得到 2026-04-02", p.NextDue)
197		}
198		// 连续撤销本段：再撤销 seq1，下一到期日恢复为其周期到期日。
199		p, _, err = s.revokeCompletion("EQ-1", seq1, "继续撤销")
200		if err != nil {
201			t.Fatalf("连续撤销本段: %v", err)
202		}
203		if p.NextDue != "2026-02-01" {
204			t.Fatalf("下一到期日 = %q，想得到 2026-02-01", p.NextDue)
205		}
206		// 旧段完成依然不能撤销。
207		if _, _, err := s.revokeCompletion("EQ-1", oldSeq, "再试旧段"); !errors.Is(err, errConflict) {
208			t.Fatalf("旧段完成仍应不能撤销，得到 %v", err)
209		}
210		// 同周期重新完成生成新序号；旧序号不能误撤销新完成。
211		_, _, seq3, err := s.completePlan("EQ-1", "2026-02-01", "2026-02-04", "重新完成")
212		if err != nil {
213			t.Fatal(err)
214		}
215		if seq3 == seq1 {
216			t.Fatal("重新完成应生成新序号")
217		}
218		if _, _, err := s.revokeCompletion("EQ-1", seq1, "旧序号"); !errors.Is(err, errConflict) {
219			t.Fatalf("旧序号的再次撤销应被拒绝，得到 %v", err)
220		}
221		if got := s.findPlan("EQ-1"); got.NextDue != "2026-04-02" {
222			t.Fatalf("旧序号撤销不应影响新完成，下一到期日 = %q", got.NextDue)
223		}
224		// 原完成的内容、日期、时间及撤销状态保留。
225		events := s.eventsOf("EQ-1")
226		var oldDone, redone *Event
227		revoked := s.revokedDoneSeqs()
228		for i := range events {
229			if events[i].Seq == oldSeq {
230				oldDone = &events[i]
231			}
232			if events[i].Seq == seq3 {
233				redone = &events[i]
234			}
235		}
236		if oldDone == nil || oldDone.Content != "旧段完成" || oldDone.Done != "2026-01-02" || oldDone.Time.IsZero() {
237			t.Fatalf("旧段完成履历应保留: %+v", oldDone)
238		}
239		if !revoked[seq1] || !revoked[seq2] || revoked[seq3] || revoked[oldSeq] {
240			t.Fatalf("撤销状态不对: %v", revoked)
241		}
242		if redone == nil || redone.Content != "重新完成" {
243			t.Fatalf("重新完成的履历应保留: %+v", redone)
244		}
245		// 重启后段边界与撤销规则保持。
246		s = saveAndReopen(t, s)
247		if _, _, err := s.revokeCompletion("EQ-1", oldSeq, "重开后试旧段"); !errors.Is(err, errConflict) {
248			t.Fatalf("重开后旧段完成仍应不能撤销，得到 %v", err)
249		}
250		if _, _, err := s.revokeCompletion("EQ-1", seq3, "重开后撤销当前段"); err != nil {
251			t.Fatalf("重开后应能撤销当前段最新完成: %v", err)
252		}
253		if got := s.findPlan("EQ-1"); got.NextDue != "2026-02-01" {
254			t.Fatalf("重开后恢复下一到期日 = %q，想得到 2026-02-01", got.NextDue)
255		}
256	}
