581			t.Fatal(err)
582		}
583		if err := s.save(); err != nil {
584			t.Fatal(err)
585		}
586		before, err := os.ReadFile(filepath.Join(s.dir, dataFileName))
587		if err != nil {
588			t.Fatal(err)
589		}
590		eventCount := len(s.data.Events)
591	
592		// 失败的调整：新首次日未严格晚于有效完成日。
593		if _, _, err := s.adjustPlan("EQ-1", "新内容", "2026-01-10", 60, "理由"); !errors.Is(err, errConflict) {
594			t.Fatalf("应拒绝，得到 %v", err)
595		}
596		if len(s.data.Events) != eventCount {
597			t.Fatal("失败的调整不应产生履历")
598		}
599		if p := s.findPlan("EQ-1"); p.Content != "更换滤芯" || p.NextDue != "2026-01-31" {
600			t.Fatalf("失败的调整不应改变计划: %+v", p)
601		}
602		// 失败不写文件：磁盘上的台账字节保持不变。
603		gotRaw, err := os.ReadFile(filepath.Join(s.dir, dataFileName))
604		if err != nil || !bytes.Equal(gotRaw, before) {
605			t.Fatal("失败的调整不应改动台账文件")
606		}
607		// 不消耗序号：随后的成功操作使用紧接着的序号。
608		p, _, err := s.adjustPlan("EQ-1", "更换高效滤芯", "2026-01-11", 60, "型号升级")
609		if err != nil {
610			t.Fatalf("adjustPlan: %v", err)
611		}
612		events := s.eventsOf("EQ-1")
613		last := events[len(events)-1]
614		if last.Kind != eventPlanAdjust || last.Seq != events[len(events)-2].Seq+1 {
615			t.Fatalf("失败不应消耗序号: %+v", last)
616		}
617		if p.NextDue != "2026-01-11" {
618			t.Fatalf("下一到期日 = %q，想得到 2026-01-11", p.NextDue)
619		}
620		if err := s.save(); err != nil {
621			t.Fatal(err)
622		}
623		// 失败本身未写文件：保存前文件字节与之前一致（由后续成功保存覆盖）。
624		s = saveAndReopen(t, s)
625		if p := s.findPlan("EQ-1"); p.Content != "更换高效滤芯" || p.FirstDue != "2026-01-11" ||
626			p.IntervalDays != 60 || p.NextDue != "2026-01-11" {
627			t.Fatalf("重载后方案未保持: %+v", p)
628		}
629		if got := len(s.eventsOf("EQ-1")); got != 3 {
630			t.Fatalf("重载后履历数 = %d，想得到 3", got)
631		}
632	}
633	
634	// 命令行入口：参数错误退出码 2，业务失败退出码 1，成功输出新方案与日期。
635	func TestCmdAdjustExitCodes(t *testing.T) {
636		dir := t.TempDir()
637		var out, errBuf bytes.Buffer
638		if code := run([]string{"register", "--data-dir", dir, "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼"}, &out, &errBuf); code != 0 {
639			t.Fatalf("register: %d %s", code, errBuf.String())
640		}
641		if code := run([]string{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "更换滤芯",
642			"--first-due", "2026-11-01", "--interval-days", "90"}, &out, &errBuf); code != 0 {
643			t.Fatalf("plan: %d %s", code, errBuf.String())
644		}
645		// 参数错误：缺理由、无效日期、非正间隔、缺内容。
646		for _, args := range [][]string{
647			{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2027-01-01", "--interval-days", "30"},
648			{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2027-13-01", "--interval-days", "30", "--reason", "r"},
649			{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2027-01-01", "--interval-days", "0", "--reason", "r"},
650			{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--first-due", "2027-01-01", "--interval-days", "30", "--reason", "r"},
651		} {
652			out.Reset()
653			if code := run(args, &out, &errBuf); code != 2 {
654				t.Fatalf("%v 应以退出码 2 失败，得到 %d", args, code)
655			}
656		}
657		// 业务失败：未知资产、无计划。
658		out.Reset()
659		if code := run([]string{"adjust", "--data-dir", dir, "--asset-id", "NOPE", "--content", "x",
660			"--first-due", "2027-01-01", "--interval-days", "30", "--reason", "r"}, &out, &errBuf); code != 1 {
661			t.Fatalf("未知资产应以退出码 1 失败，得到 %d", code)
662		}
663		if code := run([]string{"register", "--data-dir", dir, "--asset-id", "EQ-2", "--name", "空调", "--location", "二楼"}, &out, &errBuf); code != 0 {
664			t.Fatal(code)
665		}
666		if code := run([]string{"adjust", "--data-dir", dir, "--asset-id", "EQ-2", "--content", "x",
667			"--first-due", "2027-01-01", "--interval-days", "30", "--reason", "r"}, &out, &errBuf); code != 1 {
668			t.Fatalf("无计划应以退出码 1 失败，得到 %d", code)
669		}
670		// 成功：输出新方案与日期。
671		out.Reset()
672		if code := run([]string{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "更换高效滤芯",
673			"--first-due", "2027-01-01", "--interval-days", "60", "--reason", "型号升级"}, &out, &errBuf); code != 0 {
674			t.Fatalf("adjust 应成功，得到 %d: %s", code, errBuf.String())
675		}
676		for _, want := range []string{"保养内容: 更换高效滤芯", "保养间隔: 每 60 天", "首次到期日: 2027-01-01", "下一到期日: 2027-01-01"} {
677			if !strings.Contains(out.String(), want) {
678				t.Fatalf("输出缺少 %q:\n%s", want, out.String())
679			}
680		}
681		// plan 仍不能覆盖已有计划。
682		if code := run([]string{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "覆盖",
683			"--first-due", "2028-01-01", "--interval-days", "30"}, &out, &errBuf); code != 1 {
684			t.Fatalf("已有计划时 plan 应拒绝，得到 %d", code)
685		}
686	}
