510	// 撤销为一次原子保存：写入失败保留原文件字节，不留下部分变化、不消耗序号，
511	// 恢复后可重试。
512	func TestRevokeSaveFailureAndRetry(t *testing.T) {
513		s := newTestStore(t)
514		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
