518			t.Fatal(err)
519		}
520		_, _, seq1, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-01", "第一次")
521		if err != nil {
522			t.Fatal(err)
523		}
524		if err := s.save(); err != nil {
525			t.Fatal(err)
526		}
527		before := readFileBytes(t, s.dir)
528	
529		if _, _, err := s.revokeCompletion("EQ-1", seq1, "误登记"); err != nil {
530			t.Fatal(err)
531		}
532		if err := os.Chmod(s.dir, 0o555); err != nil {
533			t.Fatal(err)
534		}
535		saveErr := s.save()
536		if err := os.Chmod(s.dir, 0o755); err != nil {
537			t.Fatal(err)
538		}
539		if saveErr == nil {
540			t.Skip("当前环境忽略目录写权限，无法模拟写入失败")
541		}
542		// 原文件字节不变。
543		if got := readFileBytes(t, s.dir); !bytes.Equal(got, before) {
544			t.Fatal("写入失败不应改动原文件")
545		}
546		// 重载后看不到部分变化：下一到期日未回退，完成未撤销。
547		s2, err := openStore(s.dir)
548		if err != nil {
549			t.Fatal(err)
550		}
551		if got := s2.findPlan("EQ-1"); got.NextDue != "2026-01-11" {
552			t.Fatalf("写入失败不应留下部分变化，下一到期日 = %q", got.NextDue)
553		}
554		// 恢复后可重试：同一目标序号仍有效，撤销履历序号未消耗。
555		p, _, err := s2.revokeCompletion("EQ-1", seq1, "误登记")
556		if err != nil {
557			t.Fatalf("恢复后重试: %v", err)
558		}
559		if p.NextDue != "2026-01-01" {
560			t.Fatalf("重试后下一到期日 = %q", p.NextDue)
561		}
562		events := s2.eventsOf("EQ-1")
563		if got := events[len(events)-1].Seq; got != seq1+1 {
564			t.Fatalf("失败不应消耗履历序号，撤销序号 = %d，想得到 %d", got, seq1+1)
565		}
566		if err := s2.save(); err != nil {
567			t.Fatal(err)
568		}
569		s3, err := openStore(s.dir)
570		if err != nil {
571			t.Fatal(err)
572		}
573		if got := s3.findPlan("EQ-1"); got.NextDue != "2026-01-01" {
574			t.Fatalf("重载后下一到期日 = %q", got.NextDue)
575		}
576	}
577	
578	// maintain 显示完成履历序号；history 显示各次完成的序号及有效或已撤销状态；
579	// 参数错误退出码 2，业务失败退出码 1。
580	func TestUnmaintainCommandAndExitCodes(t *testing.T) {
581		dir := t.TempDir()
582		var out, errOut bytes.Buffer
583		runOK := func(args ...string) string {
584			t.Helper()
585			out.Reset()
586			errOut.Reset()
587			if code := run(args, &out, &errOut); code != 0 {
588				t.Fatalf("%v 应成功: %d %s", args, code, errOut.String())
589			}
590			return out.String()
591		}
592		runOK("register", "--data-dir", dir, "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼")
593		runOK("plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "更换滤芯",
594			"--first-due", "2026-01-01", "--interval-days", "10")
595		// maintain 成功显示完成履历的全库序号。
596		o := runOK("maintain", "--data-dir", dir, "--asset-id", "EQ-1",
597			"--due", "2026-01-01", "--done", "2026-01-02", "--result", "已更换")
598		if !strings.Contains(o, "完成履历序号: 2") || !strings.Contains(o, "下一到期日: 2026-01-11") {
599			t.Fatalf("maintain 输出不对:\n%s", o)
600		}
601		o = runOK("maintain", "--data-dir", dir, "--asset-id", "EQ-1",
602			"--due", "2026-01-11", "--done", "2026-01-11", "--result", "第二次")
603		if !strings.Contains(o, "完成履历序号: 3") {
604			t.Fatalf("maintain 输出不对:\n%s", o)
605		}
606	
607		// 参数错误 → 2：缺参数、非正序号。
608		for _, args := range [][]string{
609			{"unmaintain", "--data-dir", dir, "--asset-id", "EQ-1", "--reason", "x"},
610			{"unmaintain", "--data-dir", dir, "--asset-id", "EQ-1", "--seq", "4"},
611			{"unmaintain", "--data-dir", dir, "--asset-id", "EQ-1", "--seq", "-1", "--reason", "x"},
612			{"unmaintain", "--data-dir", dir, "--seq", "4", "--reason", "x"},
613		} {
614			out.Reset()
615			errOut.Reset()
616			if code := run(args, &out, &errOut); code != 2 {
617				t.Fatalf("参数错误应退出 2: %v → %d (%s)", args, code, errOut.String())
618			}
619		}
620		// 业务失败 → 1：未知资产、未知序号、非最新完成。
621		for _, args := range [][]string{
622			{"unmaintain", "--data-dir", dir, "--asset-id", "NOPE", "--seq", "3", "--reason", "x"},
623			{"unmaintain", "--data-dir", dir, "--asset-id", "EQ-1", "--seq", "99", "--reason", "x"},
624			{"unmaintain", "--data-dir", dir, "--asset-id", "EQ-1", "--seq", "2", "--reason", "x"},
625		} {
626			out.Reset()
627			errOut.Reset()
628			if code := run(args, &out, &errOut); code != 1 {
629				t.Fatalf("业务失败应退出 1: %v → %d", args, code)
630			}
631		}
632		// 成功撤销：输出目标序号与恢复的日期。
633		o = runOK("unmaintain", "--data-dir", dir, "--asset-id", "EQ-1", "--seq", "3", "--reason", "误登记")
634		if !strings.Contains(o, "序号 3") || !strings.Contains(o, "恢复下一到期日: 2026-01-11") {
635			t.Fatalf("unmaintain 输出不对:\n%s", o)
636		}
637		// 重复撤销 → 1。
638		out.Reset()
639		errOut.Reset()
640		if code := run([]string{"unmaintain", "--data-dir", dir, "--asset-id", "EQ-1", "--seq", "3", "--reason", "x"},
641			&out, &errOut); code != 1 {
642			t.Fatalf("重复撤销应退出 1，得到 %d", code)
643		}
644	
645		// history 显示各次完成的序号及有效或已撤销状态，以及撤销履历。
646		o = runOK("history", "--data-dir", dir, "--asset-id", "EQ-1")
647		for _, want := range []string{"保养完成（序号 2，有效）", "保养完成（序号 3，已撤销）",
648			"保养撤销: 目标完成履历序号 3（误登记）"} {
649			if !strings.Contains(o, want) {
650				t.Fatalf("history 缺少 %q:\n%s", want, o)
651			}
652		}
653		// 重启后结果保持。
654		o = runOK("detail", "--data-dir", dir, "--asset-id", "EQ-1")
655		if !strings.Contains(o, "下一到期日: 2026-01-11") {
656			t.Fatalf("重启后 detail 应保持回退:\n%s", o)
657		}
658	}
