140	// findPlan 返回资产的保养计划，无计划时返回 nil。
141	func (s *store) findPlan(assetID string) *Plan {
142		for _, p := range s.data.Plans {
143			if p.AssetID == assetID {
144				return p
145			}
146		}
147		return nil
148	}
149	
150	// appendMaintEvent 以给定序号追加保养履历（建立或完成）。保养履历不属于任何
151	// 工单，from/to 恒为空；due/done/interval 按履历类型使用。
152	func (s *store) appendMaintEvent(seq int, assetID, kind, content, due, done string, interval int) {
153		s.data.Events = append(s.data.Events, Event{
154			Seq:      seq,
155			AssetID:  assetID,
156			Kind:     kind,
157			Content:  content,
158			Due:      due,
159			Done:     done,
160			Interval: interval,
161			Time:     s.now(),
162		})
163	}
164	
165	// createPlan 为资产建立唯一的周期保养计划：每项资产最多一个，已有计划时拒绝，
166	// 不覆盖。业务判定全部经共用核心（checkCreatePlan）；通过后才取序号并落库，
167	// 因此任何失败路径都不修改业务数据、不消耗序号。
168	func (s *store) createPlan(assetID, content, firstDue string, intervalDays int) (*Plan, error) {
169		if err := checkCreatePlan(s.data, assetID, content, firstDue, intervalDays); err != nil {
170			return nil, err
171		}
172		eventSeq, err := s.nextEventSeq()
173		if err != nil {
174			return nil, err
175		}
176		p := &Plan{
177			AssetID:      assetID,
178			Content:      content,
179			FirstDue:     firstDue,
180			IntervalDays: intervalDays,
181			NextDue:      firstDue,
182		}
183		s.data.Plans = append(s.data.Plans, p)
184		s.appendMaintEvent(eventSeq, assetID, eventPlanCreate, content, firstDue, "", intervalDays)
185		return p, nil
186	}
187	
188	// adjustPlan 调整已有计划的保养方案：更换内容、周期起点（新首次到期日）与
189	// 间隔，理由非空；仅已有计划的资产可调整，维修中、停用时也允许。业务判定
190	// （含“新首次到期日严格晚于所有方案段内未撤销完成实际完成日”）全部经共用
191	// 核心，核心逐步重放得到当时状态而非取最终状态；通过后才取序号并落库。
192	// 成功以调整履历的全库序号开启新方案段，下一到期日设为新首次日，保留全部
193	// 历史；调整不改变资产状态、工单、请求绑定或停机统计。
194	func (s *store) adjustPlan(assetID, content, firstDue string, intervalDays int, reason string) (*Plan, *Plan, error) {
195		rr, err := replayAllMaintenance(s.data)
196		if err != nil {
197			return nil, nil, fmt.Errorf("保养履历无法核对：%w", err)
198		}
199		oldSpec, err := checkAdjustPlan(s.data, rr, assetID, content, firstDue, intervalDays, reason)
200		if err != nil {
201			return nil, nil, err
202		}
203		eventSeq, err := s.nextEventSeq()
204		if err != nil {
205			return nil, nil, err
206		}
207		p := s.findPlan(assetID)
208		old := &Plan{
209			AssetID:      assetID,
210			Content:      oldSpec.content,
211			FirstDue:     oldSpec.firstDue,
212			IntervalDays: oldSpec.interval,
213			NextDue:      p.NextDue,
214		}
215		s.data.Events = append(s.data.Events, Event{
216			Seq:         eventSeq,
217			AssetID:     assetID,
218			Kind:        eventPlanAdjust,
219			Content:     reason,
220			Due:         firstDue,
221			Interval:    intervalDays,
222			NewContent:  content,
223			OldContent:  oldSpec.content,
224			OldDue:      oldSpec.firstDue,
225			OldInterval: oldSpec.interval,
226			OldNextDue:  p.NextDue,
227			Time:        s.now(),
228		})
229		p.Content = content
230		p.FirstDue = firstDue
231		p.IntervalDays = intervalDays
232		p.NextDue = firstDue
233		return p, old, nil
234	}
235	
236	// completePlan 登记当前方案段下一周期的保养完成。业务判定（接续当时下一
237	// 到期日、完成日不早于周期到期日、按当段方案推进、越界整次拒绝、停用拒绝）
238	// 全部经共用核心，核心逐步重放得到当时方案段与下一到期日；通过后才取序号
239	// 并落库，因此失败路径不推进日期、不新增履历、不消耗序号。返回完成履历的
240	// 全库序号。
241	func (s *store) completePlan(assetID, due, done, result string) (*Plan, string, int, error) {
242		rr, err := replayAllMaintenance(s.data)
243		if err != nil {
244			return nil, "", 0, fmt.Errorf("保养履历无法核对：%w", err)
245		}
246		next, err := checkCompletePlan(s.data, rr, assetID, due, done, result)
247		if err != nil {
248			return nil, "", 0, err
249		}
250		eventSeq, err := s.nextEventSeq()
251		if err != nil {
252			return nil, "", 0, err
253		}
254		p := s.findPlan(assetID)
255		p.NextDue = next
256		s.appendMaintEvent(eventSeq, assetID, eventPlanDone, result, due, done, 0)
257		return p, p.NextDue, eventSeq, nil
258	}
259	
260	// revokedDoneSeqs 返回已被撤销的保养完成履历序号集合。
261	func (s *store) revokedDoneSeqs() map[int]bool {
262		revoked := map[int]bool{}
263		for _, e := range s.data.Events {
264			if e.Kind == eventPlanRevoke {
265				revoked[e.TargetSeq] = true
266			}
267		}
268		return revoked
269	}

